/**
 * One attachment on an outgoing email: either base64 `content`, or a Puter FS
 * reference (`path`/`uid`). How a reference is read depends on the method:
 * `sendTransactional()` streams it server-side with the caller's (falling back
 * to the authorizing worker's) file permissions, so prefer it for anything
 * larger than a few hundred kilobytes; `send()` reads it in the client before
 * composing the message.
 */
export type EmailAttachment = {
    /**
     * Required with `content`; defaults to the file's name for FS refs.
     */
    filename?: string | undefined;
    /**
     * Base64 file body. Mutually exclusive with `path`/`uid`.
     */
    content?: string | undefined;
    /**
     * Puter FS path (supports `~/`). Mutually exclusive with `content`.
     */
    path?: string | undefined;
    /**
     * Puter FS entry uid. Mutually exclusive with `content`.
     */
    uid?: string | undefined;
    /**
     * MIME type of the attachment.
     */
    contentType?: string | undefined;
    /**
     * Content-ID for an inline part, which the `html` body shows with
     * `<img src="cid:...">`. Printable ASCII without whitespace or angle brackets.
     */
    cid?: string | undefined;
};
/**
 * Which mailbox folder to read. `inbox` holds mail received at the user's
 * address, `sent` the user's own outgoing copies.
 */
export type EmailFolder = "inbox" | "sent";
/**
 * One message as it appears in a listing. Built from the mailbox listing
 * alone, without opening the message, so `subject` is the first 80 characters
 * only and there is no sender: call `puter.email.get()` for the rest.
 */
export type EmailSummary = {
    /**
     * Message id (a uuidv7); pass it to `get()`.
     */
    id: string;
    /**
     * Subject, possibly truncated to 80 characters.
     */
    subject: string;
    /**
     * ISO 8601 timestamp of when the message was filed.
     */
    date: string;
    /**
     * Size of the raw message in bytes.
     */
    size: number;
    /**
     * The folder the message was listed from.
     */
    folder: EmailFolder;
    /**
     * Filesystem path of the raw `message/rfc822` object.
     */
    path: string;
    /**
     * Filesystem uid of the raw object.
     */
    uid: string;
};
/**
 * A parsed mailbox: `{ name, address }`, or a named group of them.
 */
export type EmailAddress = import("postal-mime").Address;
/**
 * One header of a parsed message.
 */
export type EmailHeader = import("postal-mime").Header;
/**
 * One attachment of a message returned by `get()`, bytes included.
 */
export type EmailMessageAttachment = {
    filename: string | null;
    mimeType: string;
    disposition: "attachment" | "inline" | null;
    /**
     * `Content-ID`, without the angle brackets, for inline references.
     */
    contentId?: string | undefined;
    /**
     * `true` for parts referenced from the HTML body (inline images).
     */
    related?: boolean | undefined;
    /**
     * Byte length of `content`.
     */
    size: number;
    /**
     * The decoded attachment bytes.
     */
    content: ArrayBuffer;
};
/**
 * A fully parsed message, as returned by `get()`.
 */
export type EmailMessage = EmailSummary & {
    messageId: string | null;
    inReplyTo: string | null;
    references: string | null;
    from: EmailAddress | null;
    to: EmailAddress[];
    cc: EmailAddress[];
    bcc: EmailAddress[];
    replyTo: EmailAddress[];
    headers: EmailHeader[];
    text: string | null;
    html: string | null;
    attachments: EmailMessageAttachment[];
};
/**
 * Options for `list()`. Results are newest first. Every call returns one page;
 * pass the page's `cursor` back to fetch the next one.
 */
export type EmailListOptions = {
    /**
     * Folder to list. Default `'inbox'`.
     */
    folder?: EmailFolder | undefined;
    /**
     * Maximum messages per page. Default 50, capped at 1000.
     */
    limit?: number | undefined;
    /**
     * Opaque continuation cursor from a previous page; `null` or absent for the first page.
     */
    cursor?: string | null | undefined;
};
/**
 * The `stream: true` form of `list()`: an async iterator of pages.
 */
export type EmailListStreamOptions = EmailListOptions & {
    stream: true;
};
/**
 * The options form of `get()`.
 */
export type EmailGetOptions = {
    /**
     * Message id, from a listing.
     */
    id: string;
    /**
     * Folder the message is in. Default `'inbox'`.
     */
    folder?: EmailFolder | undefined;
    /**
     * When `true`, resolve with the raw `message/rfc822` bytes as a `Blob` instead of parsing.
     */
    raw?: boolean | undefined;
};
